using System.ComponentModel.DataAnnotations;

namespace sv_24ab6dbd99be474495f75a602297d633.Services;

public class BookAppointmentModelMetadata : BookAppointmentModel { }

public partial class BookAppointmentModel : IValidatableObject
{
    [Required(ErrorMessage = "Patient name is required")]
    public string? PatientName { get; set; }

    [Required(ErrorMessage = "Email is required")]
    [EmailAddress(ErrorMessage = "Invalid email format")]
    public string? Email { get; set; }

    [Required(ErrorMessage = "Phone is required")]
    public string? Phone { get; set; }

    [Required(ErrorMessage = "Insurance provider is required")]
    public string InsuranceProvider { get; set; } = "";

    public string? Doctor { get; set; }

    public DateOnly? AppointmentDate { get; set; }

    public string? TimeSlot { get; set; }

    [MaxLength(500, ErrorMessage = "Reason must be 500 characters or fewer")]
    public string? Reason { get; set; }

    public IEnumerable<ValidationResult> Validate(ValidationContext validationContext)
    {
        // Step 2 fields are only required when Doctor is being filled (step 2 visible)
        // We handle this conditionally - if Doctor has a value, we're in step 2
        if (Doctor is not null || AppointmentDate.HasValue || TimeSlot is not null || Reason is not null)
        {
            if (string.IsNullOrWhiteSpace(Doctor))
                yield return new ValidationResult("Preferred doctor is required", [nameof(Doctor)]);

            if (!AppointmentDate.HasValue)
                yield return new ValidationResult("Date is required", [nameof(AppointmentDate)]);
            else if (AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
                yield return new ValidationResult("Date must be in the future", [nameof(AppointmentDate)]);

            if (string.IsNullOrWhiteSpace(TimeSlot))
                yield return new ValidationResult("Time slot is required", [nameof(TimeSlot)]);

            if (string.IsNullOrWhiteSpace(Reason))
                yield return new ValidationResult("Reason for visit is required", [nameof(Reason)]);
        }
    }
}

